// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(address to, uint256 id, address from, bytes memory data) public {
        // Restrict to, from to be non-zero if needed, but keep wide
        vm.assume(to != address(0));
        vm.assume(from != address(0));
        vm.assume(to != address(c)); // avoid self-transfer complications
        // data can be anything

        // We drive the public entry onERC721Received directly on c
        bytes4 result;
        try c.onERC721Received(address(0), from, id, data) returns (bytes4 ret) {
            result = ret;
        } catch {
            // If it reverts, we treat as not equal to selector
            result = bytes4(0);
        }

        // The universal property: the return value must equal ERC721TokenReceiver.onERC721Received.selector
        // This holds for all valid inputs in the reference, but fails for mutated version.
        assertTrue(result == 0x150b7a02);
    }
}

