pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address sender, uint256 id, bytes calldata data) public {
        // Call onERC721Received and capture the returned bytes4 value.
        bool success;
        bytes memory retData;
        (success, retData) = address(c).call(abi.encodeWithSignature("onERC721Received(address,address,uint256,bytes)", sender, address(this), id, data));
        require(success, "call failed");
        bytes4 ret = abi.decode(retData, (bytes4));
        // The reference contract always returns the expected selector.
        assertTrue(ret == 0x150b7a02);
    }
}

