pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // The only constraint: keep feeRate in the range that could be affected (0 to 10000)
        vm.assume(_feeRate <= 10000);
        // All other arguments are irrelevant for this property; use dummy values
        address _baseToken = address(0);
        address _nft = address(0);
        uint128 _virtualBaseTokenReserves = 0;
        uint128 _virtualNftReserves = 0;
        uint56 _changeFee = 0;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;

        bool success;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            success = true;
        } catch {
            success = false;
        }

        if (success) {
            // If initialization succeeded, feeRate must not exceed 5000
            assertTrue(c.feeRate() <= 5000);
